"""Tests for tasks_api.queries — TaskQuery, apply_query, TaskPage."""

from __future__ import annotations

from datetime import datetime, timezone, timedelta

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query
from tests.conftest import FIXED_NOW, make_task


# ── TaskQuery validation ────────────────────────────────────────────────────

class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("bad_sort", ["id", "unknown", ""])
    def test_rejects_invalid_sort_field(self, bad_sort):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort=bad_sort)

    @pytest.mark.parametrize("bad_limit", [0, -1, 101, "five"])
    def test_rejects_invalid_limit(self, bad_limit):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=bad_limit)

    @pytest.mark.parametrize("bad_offset", [-1, "abc"])
    def test_rejects_invalid_offset(self, bad_offset):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=bad_offset)

    def test_tag_normalized(self):
        q = TaskQuery(tag="  Hello  ")
        assert q.tag == "hello"

    def test_tag_invalid_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad char!")

    def test_search_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"

    def test_search_blank_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_valid_sort_fields(self):
        for field in ("created_at", "due_at", "priority", "title"):
            q = TaskQuery(sort=field)
            assert q.sort == field


# ── TaskPage ────────────────────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[make_task()], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[make_task()], total=1, limit=20, offset=0)
        assert page.has_more is False

    def test_has_more_false_exact_boundary(self):
        items = [make_task(task_id=i) for i in range(3)]
        page = TaskPage(items=items, total=3, limit=10, offset=0)
        assert page.has_more is False


# ── apply_query: filtering ──────────────────────────────────────────────────

class TestApplyQueryFiltering:
    @pytest.fixture
    def sample_tasks(self):
        past = FIXED_NOW - timedelta(days=10)
        future = FIXED_NOW + timedelta(days=10)
        return [
            make_task(task_id=1, title="Buy milk", status=TaskStatus.PENDING,
                      priority=TaskPriority.LOW, due_at=past, tags=[Tag("shopping")]),
            make_task(task_id=2, title="Write report", status=TaskStatus.DONE,
                      priority=TaskPriority.HIGH, due_at=future, tags=[Tag("work")]),
            make_task(task_id=3, title="Call dentist", status=TaskStatus.PENDING,
                      priority=TaskPriority.MEDIUM, tags=[Tag("health"), Tag("shopping")]),
        ]

    def test_no_filters_returns_all(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(), FIXED_NOW)
        assert page.total == 3

    def test_filter_by_status_pending(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(status=TaskStatus.PENDING), FIXED_NOW)
        assert page.total == 2
        assert all(t.status == TaskStatus.PENDING for t in page.items)

    def test_filter_by_status_done(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(status=TaskStatus.DONE), FIXED_NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(tag="shopping"), FIXED_NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 3}

    def test_filter_by_search(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(search="milk"), FIXED_NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_search_is_case_insensitive(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(search="REPORT"), FIXED_NOW)
        assert page.total == 1

    def test_filter_overdue_true(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(overdue=True), FIXED_NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_filter_overdue_false(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(overdue=False), FIXED_NOW)
        assert page.total == 2
        assert 1 not in {t.id for t in page.items}

    def test_combined_filters(self, sample_tasks):
        page = apply_query(
            sample_tasks,
            TaskQuery(status=TaskStatus.PENDING, tag="shopping"),
            FIXED_NOW,
        )
        assert page.total == 2


# ── apply_query: sorting ────────────────────────────────────────────────────

class TestApplyQuerySorting:
    def test_sort_by_title_ascending(self):
        tasks = [make_task(task_id=1, title="Zebra"), make_task(task_id=2, title="Alpha")]
        page = apply_query(tasks, TaskQuery(sort="title"), FIXED_NOW)
        assert [t.title for t in page.items] == ["Alpha", "Zebra"]

    def test_sort_by_title_descending(self):
        tasks = [make_task(task_id=1, title="Alpha"), make_task(task_id=2, title="Zebra")]
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), FIXED_NOW)
        assert [t.title for t in page.items] == ["Zebra", "Alpha"]

    def test_sort_by_priority(self):
        tasks = [
            make_task(task_id=1, priority=TaskPriority.LOW),
            make_task(task_id=2, priority=TaskPriority.HIGH),
            make_task(task_id=3, priority=TaskPriority.MEDIUM),
        ]
        page = apply_query(tasks, TaskQuery(sort="priority"), FIXED_NOW)
        assert [t.priority for t in page.items] == [
            TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW
        ]

    def test_sort_by_due_at_none_last(self):
        future = FIXED_NOW + timedelta(days=5)
        tasks = [
            make_task(task_id=1, due_at=None),
            make_task(task_id=2, due_at=future),
        ]
        page = apply_query(tasks, TaskQuery(sort="due_at"), FIXED_NOW)
        assert page.items[0].id == 2
        assert page.items[1].id == 1

    def test_sort_by_created_at(self):
        t1 = make_task(task_id=1, created_at=FIXED_NOW - timedelta(days=1))
        t2 = make_task(task_id=2, created_at=FIXED_NOW)
        page = apply_query([t2, t1], TaskQuery(sort="created_at"), FIXED_NOW)
        assert [t.id for t in page.items] == [1, 2]


# ── apply_query: pagination ─────────────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def many_tasks(self):
        return [make_task(task_id=i, title=f"Task {i}") for i in range(1, 11)]

    def test_limit(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(limit=3), FIXED_NOW)
        assert len(page.items) == 3
        assert page.total == 10
        assert page.has_more is True

    def test_offset(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(limit=3, offset=8), FIXED_NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_total(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(offset=100), FIXED_NOW)
        assert len(page.items) == 0
        assert page.total == 10
        assert page.has_more is False

